// bpb-xray is the Windows process entry point for BPB's pinned Xray-core fork.
// The Flutter desktop app owns this process and supplies a config generated by the
// existing Dart XrayConfigBuilder. TUN mode is intentionally not exposed here yet.
package main

import (
	"flag"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"bpb/xray"
)

func main() {
	configPath := flag.String("config", "", "path to the Xray JSON config")
	assetDir := flag.String("asset-dir", "", "directory containing geoip.dat, geosite.dat and certificates")
	flag.Parse()

	if *configPath == "" {
		fmt.Fprintln(os.Stderr, "missing required -config")
		os.Exit(2)
	}
	if *assetDir != "" {
		xray.InitEnv(*assetDir)
	}

	config, err := os.ReadFile(*configPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "read config: %v\n", err)
		os.Exit(1)
	}

	controller := xray.NewController()
	if err := controller.Start(string(config), 0); err != nil {
		fmt.Fprintf(os.Stderr, "start Xray: %v\n", err)
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "BPB Xray %s started (proxy process)\n", xray.Version())

	signals := make(chan os.Signal, 1)
	signal.Notify(signals, os.Interrupt, syscall.SIGTERM)
	<-signals
	if err := controller.Stop(); err != nil {
		fmt.Fprintf(os.Stderr, "stop Xray: %v\n", err)
		os.Exit(1)
	}
}
